begin;
create temporary table fixture as select gen_random_uuid() as business,gen_random_uuid() as other_business,gen_random_uuid() as day,gen_random_uuid() as actor,gen_random_uuid() as driver,gen_random_uuid() as outsider,gen_random_uuid() as ready_order,gen_random_uuid() as active_order,gen_random_uuid() as paid_order,gen_random_uuid() as done_order,gen_random_uuid() as handoff_order;
insert into auth.users(id,email,email_confirmed_at) select id,'rollback-'||id||'@example.invalid',now() from fixture f cross join lateral unnest(array[f.actor,f.driver,f.outsider]) id;
insert into public.bjta_businesses(id,name) select business,'Order checks fixture' from fixture union all select other_business,'Other fixture' from fixture;
insert into public.bjta_staff(business_id,user_id,display_name,roles) select business,actor,'Alex',array['order_staff','driver'] from fixture union all select business,driver,'Taylor',array['driver'] from fixture union all select other_business,outsider,'Other',array['order_staff'] from fixture;
select set_config('request.jwt.claim.sub',actor::text,true) from fixture;
insert into public.bjta_days(id,business_id,delivery_date,kitchen_address) select day,business,(now() at time zone 'America/Indiana/Indianapolis')::date,'Fixture origin' from fixture;
insert into public.bjta_deliveries(id,day_id,details,status,claimed_by,paid,payment_method) select ready_order,day,'{"name":"Ready"}'::jsonb,'ready',null,false,null from fixture union all select active_order,day,'{"name":"Active"}'::jsonb,'in_progress',driver,false,null from fixture union all select paid_order,day,'{"name":"Paid"}'::jsonb,'ready',null,true,'Cash' from fixture union all select done_order,day,'{"name":"Done"}'::jsonb,'delivered',driver,true,'Zelle' from fixture union all select handoff_order,day,'{"name":"Handoff"}'::jsonb,'in_progress',driver,false,null from fixture;
create function pg_temp.expect_error(statement text, expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;else raise;end if;end;raise exception 'Expected failure: %',expected;end$$;
do $$declare names jsonb;begin select public.gldd_order_authors(business) into names from fixture;if jsonb_array_length(names)<>5 or exists(select 1 from jsonb_array_elements(names) n where n->>'name'<>'Alex' or n ? 'email' or n ? 'roles') then raise exception 'Order attribution failed';end if;end$$;
select pg_temp.expect_error(format('select public.gldd_order_authors(%L)',other_business),'Order access required') from fixture;
select (public.gldd_cancel_delivery(ready_order,'Customer request')).status as cancelled_ready from fixture;
select (public.gldd_cancel_delivery(active_order,'Customer request')).status as cancelled_in_progress from fixture;
select pg_temp.expect_error(format('select public.gldd_cancel_delivery(%L,%L)',paid_order,'Request'),'recorded payment') from fixture;
select pg_temp.expect_error(format('select public.gldd_cancel_delivery(%L,%L)',done_order,'Request'),'Completed or cancelled') from fixture;
select set_config('request.jwt.claim.sub',driver::text,true) from fixture;
select pg_temp.expect_error(format('select public.gldd_cancel_delivery(%L,%L)',handoff_order,'Request'),'Order staff access required') from fixture;
select pg_temp.expect_error(format('select public.gldd_order_authors(%L)',business),'Order access required') from fixture;
do $$declare dto jsonb;begin select public.gldd_driver_day(business) into dto from fixture;if not exists(select 1 from jsonb_array_elements(dto->'rows') r where r->>'taken_by_name'='Alex') then raise exception 'Driver attribution missing';end if;if exists(select 1 from jsonb_array_elements(dto->'rows') r where r ? 'email' or r ? 'roles') then raise exception 'Private account data exposed';end if;end$$;
select set_config('request.jwt.claim.sub',(select user_id::text from gldd_private.app_owner limit 1),true);
select public.gldd_request_handoff(day,driver,actor,array[handoff_order],'Fixture handoff','Fixture meeting') from fixture;
select set_config('request.jwt.claim.sub',actor::text,true) from fixture;
select pg_temp.expect_error(format('select public.gldd_cancel_delivery(%L,%L)',handoff_order,'Request'),'pending handoff') from fixture;
do $$begin if (select count(*) from public.bjta_events e join fixture f on e.day_id=f.day where action='delivery_cancelled')<>2 then raise exception 'Missing cancellation events';end if;end$$;
select 'Order authors, cancellation permissions, payment/completion/handoff protections passed' result;
rollback;
